def skill():
    P = {1: Rational(1, 9), 2: Rational(4, 9), 3: Rational(4, 9)}
    assert sum(P.values()) == 1
    v = 2*P[1]*P[3] + P[2]**2
    return v.p + v.q

def standard():
    from itertools import product
    tot = Fraction(0)
    for eye in range(1, 7):
        for eye2 in range(1, 7):
            balls1 = [1, 2, 3] if eye <= 2 else [2, 3]
            balls2 = [1, 2, 3] if eye2 <= 2 else [2, 3]
            for x, y in product(balls1, balls2):
                if x + y == 4:
                    tot += Fraction(1, 36) * Fraction(1, len(balls1)) * Fraction(1, len(balls2))
    return tot.numerator + tot.denominator

def unique():
    return [standard()]
